      name.hashCode ^
      kind.hashCode ^
      x.hashCode ^
      y.hashCode ^
      rotation.hashCode ^
      scale.hashCode ^
      amount.hashCode ^
      extent.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is BridgePuppetPin &&
