enum BridgeTransformPair {
  anchor,
  position,
  scale,
  ;
}

/// Which transform property an edit names ([`lumit_core::model::TransformProp`]).
enum BridgeTransformProp {
  anchorX,
  anchorY,
  positionX,
  positionY,
  positionZ,
  scaleX,
  scaleY,
  rotation,
  rotationX,
  rotationY,
  opacity,
  ;
}

/// One vertex of a mask's path (K-222): where it sits in **layer space**, and
/// the two tangent handles that shape the curve either side of it.
///
/// Tangents are offsets *from* the vertex, in the same layer pixels — the shape
/// `lumit-core`'s `mask::Vertex` uses, carried across unchanged so a path never
/// changes meaning by crossing the bridge. A corner vertex is one with both
/// tangents at zero.
class BridgeVertex {
  final double x;
  final double y;
  final double tanInX;
  final double tanInY;
  final double tanOutX;
  final double tanOutY;

  const BridgeVertex({
    required this.x,
    required this.y,
    required this.tanInX,
    required this.tanInY,
    required this.tanOutX,
    required this.tanOutY,
  });

  @override
  int get hashCode =>
      x.hashCode ^
      y.hashCode ^
      tanInX.hashCode ^
      tanInY.hashCode ^
      tanOutX.hashCode ^
      tanOutY.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is BridgeVertex &&
          runtimeType == other.runtimeType &&
          x == other.x &&
          y == other.y &&
          tanInX == other.tanInX &&
          tanInY == other.tanInY &&
          tanOutX == other.tanOutX &&
          tanOutY == other.tanOutY;
}

class LayerReference {
  final UuidValue internalprojectId;
  final UuidValue internalcompId;
  final UuidValue internallayerId;

  const LayerReference({
    required this.internalprojectId,
    required this.internalcompId,
    required this.internallayerId,
  });

  /// Append the built-in effect named `name` to this layer's stack — or, when
  /// `name` is a **driver**, to this layer's graph.
  ///
  /// Seeded at composition size, because a few effects' defaults are positions
  /// (a transform's anchor and position start at the centre of the frame), and
  /// a fresh effect should look like identity rather than dragging the picture
  /// to a corner. An unknown name is refused; nothing partial is committed.
  ///
  /// **The fork is here rather than in each caller.** A driver is browsed as
  /// one more Controls entry, so the console, the Effect menu, the palette and
  /// the browser all offer one — and a driver on an effect *stack* would be a
  /// node that changes no pixel. Every one of those routes goes through this
  /// method, so the one question "is this a driver" is asked once and the node
  /// lands on the graph, unwired and unplaced (the panel auto-places a node
  /// with no layout entry). One op either way, so one undo step either way.
  void addEffect({required String name}) => BridgeLib.instance.api
      .crateApiLayerLayerReferenceAddEffect(that: this, name: name);

  /// Add `mask` to the top of this layer's stack.
  ///
  /// The whole list is committed, because that is the op the engine has and
  /// it is exactly invertible (`SetLayerMasks`) — an add, a delete and a
  /// reorder are all one shape of edit, and each is one undo step.
  ///
  /// A path of fewer than two vertices is refused: it is not a shape, and a
  /// mask that gates nothing would be a row in the Timeline with nothing
  /// behind it.
  void addMask({required BridgeMask mask}) => BridgeLib.instance.api
      .crateApiLayerLayerReferenceAddMask(that: this, mask: mask);

  /// Add a pin to this layer's puppet. Errors when there is no block yet:
  /// the first pin is what creates one, and it is the click that decides the
  /// reference time, so the caller says so with [`Self::set_puppet`].
  void addPuppetPin({required BridgePuppetPin pin}) => BridgeLib.instance.api
      .crateApiLayerLayerReferenceAddPuppetPin(that: this, pin: pin);

  /// Add one piece of art on top of this shape layer's stack.
  void addShapeItem({required BridgeShapeItem item}) => BridgeLib.instance.api
      .crateApiLayerLayerReferenceAddShapeItem(that: this, item: item);

  /// Add `stroke` on top of this layer's paint.
  ///
  /// The whole list is committed, because that is the op the engine has and
  /// it is exactly invertible (`SetLayerPaint`): one stroke is one undo step,
  /// which is what `Ctrl+Z` after a brush drag has to mean.
  ///
  /// A stroke with no points is refused — there is no gesture in it, and it
  /// would be a Timeline row with nothing behind it.
  void addStroke({required BridgeStroke stroke}) => BridgeLib.instance.api
      .crateApiLayerLayerReferenceAddStroke(that: this, stroke: stroke);

  /// The layer's source audio summarised across `[start_seconds,
  /// end_seconds)` of the **layer's own clock**, in `buckets` buckets
  /// (K-280, superseding the fixed 2 048 of K-172).
  ///
  /// Layer time, not comp time, is what makes a trim or a drag free: the
  /// window is fixed to where the layer starts its source, so the Timeline's
  /// lane maps it through the live in/out/offset each paint and the
  /// transients travel with the bar. The *window* is what makes the
  /// resolution follow the zoom — a lane showing two seconds asks for two
  /// seconds, and gets a bucket per pixel column of them, however far in the
  /// Timeline is zoomed.
  ///
  /// **A retimed layer's wave stretches with its map** (K-436). Layer time
  /// and source time are the same line only while the layer plays at speed
  /// 1; once it has a Retime ([`lumit_core::model::Layer::source_time_at`])
  /// they are not, and buckets taken evenly in source time would put the
  /// transients in the wrong columns — a half-speed layer's wave would fill
  /// half its bar and stop. So each bucket's edges are mapped through that
  /// map here, exactly as a Sequence clip's are through its own
  /// ([`Self::clip_audio_peaks`]): the lane still draws bucket `i` at column
  /// `i`, and a slow passage is drawn wide because it *is* wide. An
  /// un-retimed layer maps through the identity and takes the straight,
  /// one-pass path it always did.
  ///
  /// `multiwave` asks for the three-band stack (bass, middle, treble) instead
  /// of the single full-range wave.
  ///
  /// Deliberately not `#[frb(sync)]`: the first ask for a file decodes it.
  /// Every later ask, at every zoom, is served from the session's peak cache
  /// ([`crate::peaks`]) and costs a walk over a few thousand summaries.
  /// Empty when the layer has no decodable audio.
  Future<BridgeAudioPeaks> audioPeaks(
          {required double startSeconds,
          required double endSeconds,
          required int buckets,
          required bool multiwave}) =>
      BridgeLib.instance.api.crateApiLayerLayerReferenceAudioPeaks(
          that: this,
          startSeconds: startSeconds,
          endSeconds: endSeconds,
          buckets: buckets,
          multiwave: multiwave);

  /// One window of this layer's audio as a **spectrogram** (K-699): what the
  /// spectral lane mode draws, in the same window-fetch shape the peaks take
  /// (K-280) — the visible stretch of the source, one column per pixel, so
  /// the drawn detail follows the zoom.
  ///
  /// Columns are `lumit_audio::spectra::BINS` bytes each, column-major, low
  /// band first: byte 0 of a column is the bottom of the picture. A retimed
  /// layer's columns are taken through its map, exactly as its peaks are
  /// (K-436).
  ///
  /// Deliberately not `#[frb(sync)]`: the first ask for a file decodes it
  /// and runs the analysis. Every later ask, at every zoom, is served from
  /// the session's spectrogram cache ([`crate::peaks`]). Empty when the
  /// layer has no decodable audio.
  Future<BridgeSpectrogram> audioSpectrogram(
          {required double startSeconds,
          required double endSeconds,
          required int columns}) =>
      BridgeLib.instance.api.crateApiLayerLayerReferenceAudioSpectrogram(
          that: this,
          startSeconds: startSeconds,
          endSeconds: endSeconds,
          columns: columns);

  /// Stop the shape animating, keeping the shape it shows at `time` (K-340).
  ///
  /// The stopwatch turning off, and it matches what the stopwatch does
  /// everywhere else: the value that stays is the one the curve reads *at the
  /// playhead*, not the first key's — so the picture does not jump when
  /// animation is switched off.
  void clearMaskPathKeys(
          {required UuidValue id, required BridgeRational time}) =>
      BridgeLib.instance.api.crateApiLayerLayerReferenceClearMaskPathKeys(
          that: this, id: id, time: time);

  /// Stop this item's shape animating, keeping the shape it shows at `time`
  /// (K-606) — the stopwatch turning off, and what it does everywhere else:
  /// the shape that stays is the one the playhead is over, so the picture
  /// does not jump.
  void clearShapePathKeys(
          {required UuidValue id, required BridgeRational time}) =>
      BridgeLib.instance.api.crateApiLayerLayerReferenceClearShapePathKeys(
          that: this, id: id, time: time);

  /// One Sequence clip's audio, summarised in `buckets` across the clip's own
  /// placed span — the waveform a clip draws inside itself (K-280).
  ///
  /// Bucketed in **clip-local placed time**, not source time, because a clip
  /// is the one thing on the timeline whose source clock is not a straight
  /// line: a ramp plays its middle slowly and its end fast, and buckets taken
  /// evenly in source time would put the transients in the wrong columns. So
  /// each bucket is mapped through the clip's own map here, where that map
  /// lives, and the lane draws bucket `i` at column `i` of the clip's box.
  /// Sliding the clip along the row moves the picture with it for free; a
  /// trim changes the mapping, so the lane asks again when the trim commits.
  ///
  /// `[start_seconds, end_seconds)` is the stretch of the clip's own placed
  /// clock to summarise, clamped to the clip; pass the clip's whole span for
  /// the whole clip, or the visible part of it to keep the detail level with
  /// the zoom. An empty or backwards range is read as the whole clip.
  ///
  /// `multiwave` asks for the three-band stack, exactly as for a layer. Empty
  /// for a clip cut from a comp or from media with no sound.
  Future<BridgeAudioPeaks> clipAudioPeaks(
          {required UuidValue clip,
          required double startSeconds,
          required double endSeconds,
          required int buckets,
          required bool multiwave}) =>
      BridgeLib.instance.api.crateApiLayerLayerReferenceClipAudioPeaks(
          that: this,
          clip: clip,
          startSeconds: startSeconds,
          endSeconds: endSeconds,
          buckets: buckets,
          multiwave: multiwave);

  /// A thumbnail of the **first frame this clip shows** (K-248).
  ///
  /// Not the file's first frame: a clip after a cut starts part way in, and
  /// a row of thumbnails that all showed frame zero would say nothing about
  /// which clip is which. The moment is read through the clip's own map, so
  /// a re-speeded clip still shows the frame it actually opens on.
  ///
  /// `None` when the media will not open, when the source is a comp rather
  /// than footage (there is nothing on disk to decode), or in a build with
  /// no media feature. Decoded once per (item, size, frame) and cached.
  Future<BridgeRenderedFrame?> clipThumbnail(
          {required UuidValue clip, required int maxEdge}) =>
      BridgeLib.instance.api.crateApiLayerLayerReferenceClipThumbnail(
          that: this, clip: clip, maxEdge: maxEdge);

  /// Turn a Sequence layer back into a plain Footage layer (K-248).
  ///
  /// The way out of the clip-editing surface, and it must exist: converting
  /// in is offered to anyone, so a user who tries it has to be able to
  /// change their mind.
  ///
  /// **It keeps the first clip's source and its trim, and nothing else.**
  /// The cuts, the gaps and the per-clip ramps have no home on a layer that
  /// holds one uncut piece of footage, and inventing somewhere to put them
  /// would be worse than saying plainly that they go. A row of several clips
  /// is refused outright rather than silently losing all but one: the user
  /// can delete the clips they do not want first, which is a decision only
  /// they can make.
  void convertFromSequenced() =>
      BridgeLib.instance.api.crateApiLayerLayerReferenceConvertFromSequenced(
        that: this,
      );

  /// Turn a Footage layer into a Sequence layer holding one clip of the whole
  /// source — the way into the clip-editing surface.
  ///
  /// Remove-then-add at the same index rather than an in-place kind change,
  /// because a layer's kind is not something any single op edits; the batch
  /// makes it one undo step. Only footage converts.
  void convertToSequenced() =>
      BridgeLib.instance.api.crateApiLayerLayerReferenceConvertToSequenced(
        that: this,
      );

  /// This layer's effects as a `.lumfx` document, for [`Self::paste_effects`]
  /// (K-275). `effects` copies those; an empty list copies the whole stack.
  ///
  /// A list rather than one id (K-300), because an effect selection can hold
  /// several — and they come out in **stack order**, not in the order they
  /// were picked, so a copied group pastes back in the order it was drawn in.
  /// Ids that name nothing on this layer are ignored; naming none of them at
  /// all is [`BridgeError::InvalidEffect`] rather than a silent whole-stack
  /// copy.
  ///
  /// Deliberately the **same document a preset is**, so an effect copied from
  /// one layer can be saved as a preset and a preset can be pasted as an
  /// effect — one shape, not two that drift.
  String copyEffects({required List<UuidValue> effects}) =>
      BridgeLib.instance.api
          .crateApiLayerLayerReferenceCopyEffects(that: this, effects: effects);

  /// This layer as text, for [`crate::api::composition::CompositionReference::
  /// paste_layer`] — the clipboard's payload (K-275).
  ///
  /// The whole layer: its kind and source, its transform with every keyframe,
  /// its masks, paint, effects, switches, markers and retime. It is the
  /// document's own `Layer`, serialised, so anything the file format carries
  /// travels — including fields a newer Lumit added, which ride in the
  /// `extra` maps exactly as they do through a save (docs/10 §1.1).
  ///
  /// A *reference* it holds to another layer — its parent, its track matte —
  /// is copied as it stands and resolved at the paste, which is the only end
  /// that knows whether the layer being pointed at is there.
  String copyLayer() =>
      BridgeLib.instance.api.crateApiLayerLayerReferenceCopyLayer(
        that: this,
      );

  /// The shape of this Sequence layer — where its cuts fall and how each
  /// piece is ramped — as text, for [`Self::paste_sequence_shape`] (K-248).
  ///
  /// `clip` reads that clip alone; `None` reads the whole row. What comes
  /// back carries no *source*: applying it keeps the target's own media,
  /// which is the point — cutting a depth pass to the same beats as the
  /// footage it belongs to is work nobody should do twice by hand, and by
  /// eye the two always drift.
  String copySequenceShape({UuidValue? clip}) => BridgeLib.instance.api
      .crateApiLayerLayerReferenceCopySequenceShape(that: this, clip: clip);

  /// **Text to points** (K-608): a copy of this Type layer beside it, fitted
  /// with **Emit from image**, so the words become a points stream in the
  /// shape of themselves.
  ///
  /// Fill-sampled rather than walked round the outlines, because that is what
  /// the points family consumes — see the decision entry. The original is
  /// kept, as with Text to shapes, and the copy is one `Op`.
  LayerReference createPointsFromText() =>
      BridgeLib.instance.api.crateApiLayerLayerReferenceCreatePointsFromText(
        that: this,
      );

  /// **Text to shapes** (K-608): a copy of this Type layer beside it, whose
  /// picture is the glyph outlines as vector art.
  ///
  /// The original is kept and untouched, which is After Effects' convention
  /// and the only one that survives a mistake: the words are still typeable,
  /// still keyed, still expression-driven, and the copy is a drawing.
  ///
  /// Converted **at `frame`**, because a line the words of which come from an
  /// expression says something different at every frame and the honest answer
  /// is what it says at the moment the command is used. A line on a path
  /// converts curved: the outlines are placed by the same walk the rasteriser
  /// uses, so the copy lands on top of the layer it came from rather than
  /// near it.
  ///
  /// One `Op`, so one undo step — the whole layer arrives at once.
  LayerReference createShapesFromText({required PlatformInt64 frame}) =>
      BridgeLib.instance.api.crateApiLayerLayerReferenceCreateShapesFromText(
          that: this, frame: frame);

  /// Razor: cut the clip under `frame` in two, at the playhead.
  ///
  /// The two halves keep their places — a cut must not shift what comes after
  /// it, which is the beat-sync covenant (K-071). An **eased speed ramp cuts
  /// like anything else** (K-573): the map's cubic is split at the cut, so
  /// the two halves concatenate to the speed curve that was there before.
  /// What still refuses is a moment on one of the clip's own ends, and a
  /// retime driven by an expression — both calm errors rather than a cut that
  /// changes what plays.
  void cutClipAt({required PlatformInt64 frame}) => BridgeLib.instance.api
      .crateApiLayerLayerReferenceCutClipAt(that: this, frame: frame);

  /// Remove this layer from its composition.
  void delete() => BridgeLib.instance.api.crateApiLayerLayerReferenceDelete(
        that: this,
      );

  /// Take one clip off the row, by id.
  ///
  /// What it leaves is a **gap**, not a closed row: nothing after it moves,
  /// so every edit point still standing keeps the beat it was cut to
  /// (K-022). `delete_clip_at` is the same thing aimed with the playhead;
  /// this is the one the sequence view's own menu uses, because there the
  /// clip has already been pointed at.
  void deleteClip({required UuidValue clip}) => BridgeLib.instance.api
      .crateApiLayerLayerReferenceDeleteClip(that: this, clip: clip);

  /// Delete the clip under `frame`, leaving a gap.
  ///
  /// A gap is legal on the Vegas surface (K-071), so the clips after it stay
  /// where they are rather than rippling back — again so a cut never moves
  /// anything that was already in time with the music.
  void deleteClipAt({required PlatformInt64 frame}) => BridgeLib.instance.api
      .crateApiLayerLayerReferenceDeleteClipAt(that: this, frame: frame);

  /// Take the last stroke off — the undo inside the tool, for a brush drag
  /// that went wrong. Errors when there is nothing painted.
  void deleteLastStroke() =>
      BridgeLib.instance.api.crateApiLayerLayerReferenceDeleteLastStroke(
        that: this,
      );

  /// Remove a mask by id.
  void deleteMask({required UuidValue id}) => BridgeLib.instance.api
      .crateApiLayerLayerReferenceDeleteMask(that: this, id: id);

  /// Remove a pin by id. The block stays, empty if that was the last pin —
  /// the mesh is still the one the author built, and the next pin lands on
  /// it rather than on a fresh one at a different reference time.
  void deletePuppetPin({required UuidValue id}) => BridgeLib.instance.api
      .crateApiLayerLayerReferenceDeletePuppetPin(that: this, id: id);

  /// Remove a stroke by id.
  void deleteStroke({required UuidValue id}) => BridgeLib.instance.api
      .crateApiLayerLayerReferenceDeleteStroke(that: this, id: id);

  /// **Detach audio** (K-701): put this layer's sound on a row of its own.
  ///
  /// **In plain terms.** A clip that has both picture and sound arrives as
  /// one row, and everything you do to its sound — a fade, a cut, a level
  /// ride — has to be done on the row carrying the picture. Detaching makes
  /// a second row directly below that holds the *same* media as sound only,
  /// and turns the original row's speaker off. Nothing is heard twice and
  /// nothing sounds different; the sound simply has its own bar to work on,
  /// in the audio surfaces, while the picture keeps its own.
  ///
  /// The sibling is an Audio layer ([`lumit_core::model::Layer::audio_only`],
  /// K-435) over the same source, with the same span, offset, retime, volume
  /// and pan **copied** — not linked. Trimming one afterwards does not trim
  /// the other; that is what makes them separately editable, which is the
  /// point of the command. A Precomp layer detaches the same way, its sibling
  /// naming the same nested comp.
  ///
  /// **One undo step**: the sibling and the mute go in as a single
  /// [`lumit_core::Op::Batch`], so one Ctrl+Z puts the row back the way it
  /// was — and a locked layer refuses the batch whole, as the lock does
  /// everywhere.
  ///
  /// Refused with [`BridgeError::NoAudio`] on a layer that makes no sound to
  /// separate — a solid, a title, silent footage — and on a layer that is
  /// *already* only sound, which has nothing left to detach from.
  ///
  /// Not `#[frb(sync)]`: deciding whether the layer sounds opens the media
  /// with FFmpeg, exactly as [`Self::has_audio`] does, and the document lock
  /// is let go of before it.
  Future<LayerReference> detachAudio() =>
      BridgeLib.instance.api.crateApiLayerLayerReferenceDetachAudio(
        that: this,
      );

  /// Copy this layer, inserting the copy directly above the original.
  ///
  /// The copy is a fresh layer with fresh effect ids, not a second reference
  /// to the same one: two layers sharing an id would make every op that names
  /// a layer ambiguous.
  LayerReference duplicate() =>
      BridgeLib.instance.api.crateApiLayerLayerReferenceDuplicate(
        that: this,
      );

  bool equals({required LayerReference layer}) => BridgeLib.instance.api
      .crateApiLayerLayerReferenceEquals(that: this, layer: layer);

  /// **Fade the layer's sound up from silence** over `seconds` from its in
  /// point (docs/09 §6, K-695).
  ///
  /// Ordinary Volume keyframes — a pair, between the −∞ knee and whatever
  /// level the layer already holds — so the fade is visible on the row, can
  /// be dragged, reshaped in the graph, and undone like any other key. That
  /// is the whole of the command: it writes the keys a person would have
  /// written, in one step, with the right shape.
  ///
  /// Running it again over the same stretch reshapes that fade rather than
  /// laying a second one on top; keys outside it are untouched, so a fade in
  /// and a fade out coexist without either knowing about the other.
  void fadeIn({required double seconds, required BridgeFadeShape shape}) =>
      BridgeLib.instance.api.crateApiLayerLayerReferenceFadeIn(
          that: this, seconds: seconds, shape: shape);

  /// **Fade the layer's sound away to silence** over `seconds` ending at its
  /// out point — the other half of [`Self::fade_in`], same keys, same
  /// shapes, same undo step.
  void fadeOut({required double seconds, required BridgeFadeShape shape}) =>
      BridgeLib.instance.api.crateApiLayerLayerReferenceFadeOut(
          that: this, seconds: seconds, shape: shape);

  /// **Insert a freeze at the playhead** (docs/04 §7.3,
  /// `retime.freeze_at_playhead`): the moment showing at `frame` is held for
  /// one second, everything after it is pushed that far later, and the map is
  /// cropped back to the layer's own out point — so the layer's length never
  /// changes and the beat-sync covenant holds (K-022). The tail may newly
  /// overrun, which is drawn rather than repaired.
  ///
  /// One second is the specified default; the hold is two ordinary keyframes
  /// afterwards, so it is dragged like anything else.
  ///
  /// A layer with no map yet gets the identity one first — freezing a frame
  /// is a reasonable first retime to ask for, and refusing it because the
  /// stopwatch had not been touched would be a rule with no purpose.
  ///
  /// Refused on a Sequence layer (its clips carry the maps) and at a moment
  /// on or outside the layer's own ends, where there is nothing to split.
  void freezeAtPlayhead({required PlatformInt64 frame}) => BridgeLib
      .instance.api
      .crateApiLayerLayerReferenceFreezeAtPlayhead(that: this, frame: frame);

  /// This layer's blend mode, as an index into [`list_blend_modes`].
  int getBlend() => BridgeLib.instance.api.crateApiLayerLayerReferenceGetBlend(
        that: this,
      );

  /// A camera layer's zoom — focal distance in comp pixels, the After Effects
  /// model where the z=0 plane maps 1:1. `None` on any other kind.
  BridgeScalar? getCameraZoom() =>
      BridgeLib.instance.api.crateApiLayerLayerReferenceGetCameraZoom(
        that: this,
      );

  /// The clips on this Sequence layer, in the order it holds them.
  ///
  /// An empty list on a layer that is not a Sequence, rather than an error:
  /// the Timeline asks every row whether it has clips to draw, and a footage
  /// row simply has none.
  List<BridgeClip> getClips() =>
      BridgeLib.instance.api.crateApiLayerLayerReferenceGetClips(
        that: this,
      );

  List<BridgeEffectInstance> getEffects() =>
      BridgeLib.instance.api.crateApiLayerLayerReferenceGetEffects(
        that: this,
      );

  /// Whether flow is live on this layer — the switch-cluster toggle (K-088).
  bool getFlowEnabled() =>
      BridgeLib.instance.api.crateApiLayerLayerReferenceGetFlowEnabled(
        that: this,
      );

  /// The rate this clip is *interpreted* at for flow (K-095, K-160) — the
  /// Flow group's Input rate, as a keyframeable scalar.
  ///
  /// `0` reads as **Auto**: adjacent source frames, the clip's own rate. Any
  /// positive rate below native conforms the clip, so flow brackets the
  /// source frames spaced `1/rate` apart and interpolates between *those*.
  ///
  /// Two quite different footage problems want this, from opposite ends.
  /// High-speed capture — a 600 fps phone clip — has neighbours under two
  /// thousandths of a second apart, so there is almost no motion to
  /// interpolate and slow-motion looks frozen. **Animation drawn on 2s or 3s**
  /// has the mirror problem: the same frame is held two or three times, so
  /// half the pairs flow between a frame and its own duplicate (no motion at
  /// all) and the rest carry double, which reads as judder rather than smooth
  /// slow motion. Conforming to the rate the animation was *drawn* at — 12 fps
  /// for 2s of 24, 8 fps for 3s — makes every bracket span real motion.
  ///
  /// Keyframeable because a scene's cadence is not always constant: anime
  /// commonly switches between 2s and 3s within a cut, and a ramp lets the
  /// conform follow it.
  BridgeScalar getFlowInputRate() =>
      BridgeLib.instance.api.crateApiLayerLayerReferenceGetFlowInputRate(
        that: this,
      );

  /// This layer's Flow group: the live one, else the parked one it would get
  /// back on, else the defaults — so the panel can show the controls it
  /// *would* have without the policy being Flow yet.
  BridgeFlowParams getFlowParams() =>
      BridgeLib.instance.api.crateApiLayerLayerReferenceGetFlowParams(
        that: this,
      );

  /// This layer's whole driver graph in one crossing (K-471,
  /// docs/impl/node-graph.md §5) — every box the canvas draws with its
  /// sockets, plus the wiring the user edits.
  ///
  /// **One call, not one per node.** Fetched when the selection or the
  /// document changes and held in Dart; asking per node per rebuild is
  /// exactly the traffic the budget test forbids (K-183). The boxes are
  /// derived from the effect stack each time, so there is nothing stale to
  /// invalidate and nothing here to write back — see
  /// [`crate::api::graph::BridgeLayerGraph`].
  BridgeLayerGraph getGraph() =>
